<template><div class="fade-in"><div class="page-header"><h2>CỬA HÀNG GYMPRO</h2><el-badge :value="cartCount" :hidden="!cartCount"><el-button @click="tab='cart'">Giỏ hàng</el-button></el-badge></div>
<el-tabs v-model="tab" @tab-change="loadTab"><el-tab-pane label="Sản phẩm" name="products"><ShopCatalog @add="add"/></el-tab-pane>
<el-tab-pane label="Giỏ hàng" name="cart"><el-empty v-if="!cart.length" description="Giỏ hàng đang trống"/><el-card v-else><div v-for="i in cart" :key="i.cartItemId" class="cart-row"><div><b>{{i.name}}</b><div v-if="i.variantLabel" class="muted">{{i.variantLabel}}</div><div>{{money(i.unitPrice)}} × {{i.quantity}}</div></div><el-input-number :model-value="i.quantity" :min="1" :max="Math.max(1,i.stock)" :disabled="i.stock<=0" @change="q=>changeQty(i,q)"/><b>{{money(i.lineTotal)}}</b><el-button type="danger" text @click="remove(i)">Xóa</el-button></div><div class="total">Tạm tính: {{money(cartTotal)}}</div><el-button type="primary" size="large" @click="checkoutOpen=true">Đặt hàng</el-button></el-card></el-tab-pane>
<el-tab-pane label="Đơn hàng" name="orders"><el-empty v-if="!orders.length" description="Chưa có đơn hàng"/><el-card v-for="o in orders" :key="o.id" class="order"><div class="order-head"><b>Đơn #{{o.id}}</b><el-tag>{{status(o.status)}}</el-tag><b>{{money(o.total)}}</b></div><div>{{o.items.map(i=>`${i.productName}${i.variantLabel ? " ("+i.variantLabel+")" : ""} × ${i.quantity}`).join(', ')}}</div><div class="muted">{{new Date(o.createdAt).toLocaleString('vi-VN')}} · {{o.shippingAddress}}</div><el-button v-if="o.status==='PENDING_PAYMENT'" type="primary" @click="showPay(o)">Thanh toán</el-button><el-button v-if="o.status==='PENDING_PAYMENT'||(o.paymentMethod==='COD'&&o.status==='CONFIRMED')" @click="cancel(o)">Hủy đơn</el-button><el-collapse><el-collapse-item title="Lịch sử xử lý đơn"><OrderTimeline :history="o.history"/></el-collapse-item></el-collapse><el-button v-if="canReview(o)" @click="openReview(o)">Đánh giá sản phẩm</el-button></el-card></el-tab-pane></el-tabs>
<ProductVariantPicker ref="variantPicker" :add-item="addSelected"/><el-dialog v-model="reviewOpen" title="Đánh giá sản phẩm" width="520"><div v-if="reviewOrder" v-for="it in reviewOrder.items" :key="it.productId+':'+it.variantId" class="review-row"><b>{{it.productName}}</b><el-rate v-model="reviewForm[it.productId].rating"/><el-input v-model="reviewForm[it.productId].comment" type="textarea" :rows="2" placeholder="Nhận xét (không bắt buộc)"/><ShopImageEditor v-model="reviewForm[it.productId].images"/><el-button size="small" type="primary" @click="submitReview(it)">Gửi đánh giá</el-button></div></el-dialog>
<el-dialog v-model="checkoutOpen" title="Thông tin nhận hàng" width="520"><AddressBook @select="useAddress"/><el-form label-position="top"><el-form-item label="Người nhận"><el-input v-model="checkout.receiverName"/></el-form-item><el-form-item label="Số điện thoại"><el-input v-model="checkout.phone"/></el-form-item><el-form-item label="Địa chỉ giao hàng"><el-input v-model="checkout.shippingAddress" type="textarea"/></el-form-item><el-form-item label="Mã voucher"><el-input v-model="checkout.voucherCode" placeholder="Nhập mã (nếu có)"><template #append><el-button @click="applyVoucher">Áp dụng</el-button></template></el-input><el-button link type="primary" @click="applyBestVoucher">Tự chọn voucher tốt nhất</el-button></el-form-item><div v-if="voucherDiscount>0" class="muted">Giảm giá voucher: -{{money(voucherDiscount)}}</div><el-form-item label="Thanh toán"><el-select v-model="checkout.paymentMethod"><el-option label="Chuyển khoản QR" value="BANK_TRANSFER"/><el-option label="Thanh toán khi nhận hàng (COD)" value="COD"/><el-option :label="methods.MOMO?'MoMo':'MoMo — chưa cấu hình'" value="MOMO" :disabled="!methods.MOMO"/><el-option :label="methods.ZALOPAY?'ZaloPay':'ZaloPay — chưa cấu hình'" value="ZALOPAY" :disabled="!methods.ZALOPAY"/></el-select></el-form-item><el-form-item label="Ghi chú"><el-input v-model="checkout.note"/></el-form-item></el-form><template #footer><el-button @click="checkoutOpen=false">Hủy</el-button><el-button type="primary" :loading="placing" @click="placeOrder">Đặt hàng</el-button></template></el-dialog>
<el-dialog v-model="payOpen" title="Thanh toán chuyển khoản" width="520" center><div v-if="payOrder" class="pay"><h3>Đơn #{{payOrder.id}} · {{money(payOrder.total)}}</h3><img :src="qrSrc||payOrder.qrCodeUrl"/><p>Nội dung bắt buộc: <b>{{payOrder.transferCode}}</b></p><p>QR có hiệu lực 15 phút. Hệ thống tự xác nhận qua SePay.</p></div></el-dialog></div></template>
<script setup>import ShopCatalog from '@/components/shop/ShopCatalog.vue';import AddressBook from '@/components/shop/AddressBook.vue';import OrderTimeline from '@/components/shop/OrderTimeline.vue';import ShopImageEditor from '@/components/shop/ShopImageEditor.vue';import {useRoute} from 'vue-router';import ProductVariantPicker from '@/components/shop/ProductVariantPicker.vue';import{ref,computed,onMounted,watch}from'vue';import{shopAPI}from'@/api';import{ElMessage,ElMessageBox}from'element-plus';import QRCode from'qrcode';
const variantPicker=ref(null);const methods=ref({BANK_TRANSFER:true,COD:true,MOMO:false,ZALOPAY:false});const placing=ref(false);function useAddress(a){Object.assign(checkout.value,{receiverName:a.receiverName,phone:a.phone,shippingAddress:a.address})};const route=useRoute();const tab=ref(['cart','orders'].includes(route.query.tab)?route.query.tab:'products'),products=ref([]),cart=ref([]),orders=ref([]),category=ref(''),keyword=ref(''),checkoutOpen=ref(false),payOpen=ref(false),payOrder=ref(null),qrSrc=ref('');const fallback='https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=70';const checkout=ref({receiverName:'',phone:'',shippingAddress:'',note:'',voucherCode:'',paymentMethod:'BANK_TRANSFER'});const voucherDiscount=ref(0);const cartCount=computed(()=>cart.value.reduce((s,i)=>s+i.quantity,0)),cartTotal=computed(()=>cart.value.reduce((s,i)=>s+i.lineTotal,0));const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(v||0);const cat=v=>({SUPPLEMENT:'Thực phẩm bổ sung',FOOD:'Đồ ăn',EQUIPMENT:'Dụng cụ'})[v];const status=v=>({CONFIRMED:'Chờ xử lý (COD)',PENDING_PAYMENT:'Chờ thanh toán',PAID:'Đã thanh toán',PREPARING:'Đang chuẩn bị',SHIPPING:'Đang giao',DELIVERED:'Đã giao',COMPLETED:'Hoàn thành',CANCELLED:'Đã hủy',EXPIRED:'Hết hạn'})[v]||v;const reviewOpen=ref(false),reviewOrder=ref(null),reviewForm=ref({});
async function loadProducts(){products.value=(await shopAPI.products({category:category.value||undefined,keyword:keyword.value||undefined})).data||[]}async function applyBestVoucher(){try{const r=await shopAPI.bestVoucher(cart.value.map(i=>({productId:i.id,lineTotal:i.lineTotal})));if(!r.data?.code){ElMessage.info("Không có voucher phù hợp");return}checkout.value.voucherCode=r.data.code;voucherDiscount.value=r.data.discount;ElMessage.success(`Đã chọn voucher ${r.data.code}`)}catch(e){ElMessage.error("Không thể tìm voucher phù hợp")}}async function applyVoucher(){if(!checkout.value.voucherCode){voucherDiscount.value=0;return}try{const items=cart.value.map(i=>({productId:i.id,lineTotal:i.lineTotal}));const r=await shopAPI.validateVoucher(checkout.value.voucherCode,items);voucherDiscount.value=r.data.discount;ElMessage.success('Áp dụng voucher thành công')}catch(e){voucherDiscount.value=0}}async function placeOrder(){if(placing.value)return;placing.value=true;try{const r=await shopAPI.checkout(checkout.value);checkoutOpen.value=false;checkout.value.voucherCode='';voucherDiscount.value=0;await loadCart();tab.value='orders';await loadOrders();if(r.data.paymentMethod==='COD')ElMessage.success('Đã đặt đơn COD');else await showPay(r.data)}finally{placing.value=false}}async function loadCart(){cart.value=(await shopAPI.cart()).data||[]}async function loadOrders(){orders.value=(await shopAPI.orders()).data||[]}async function loadTab(){if(tab.value==='cart')await loadCart();if(tab.value==='orders')await loadOrders()}async function add(p){if(p.hasVariants){variantPicker.value.open(p);return}try{await addSelected(p)}catch{}}async function addSelected(p,v=null){await shopAPI.addCart(p.id,1,v?.id??null);ElMessage.success('Đã thêm vào giỏ');await loadCart()}async function changeQty(i,q){await shopAPI.updateCart(i.cartItemId,q);await loadCart()}async function remove(i){await shopAPI.removeCart(i.cartItemId);await loadCart()}async function showPay(o){if(['MOMO','ZALOPAY'].includes(o.paymentMethod)){const r=await shopAPI.startPayment(o.id);window.location.assign(r.data.payUrl);return}payOrder.value=o;qrSrc.value=o.qrRawPayload?await QRCode.toDataURL(o.qrRawPayload,{width:260}):'';payOpen.value=true}async function cancel(o){await ElMessageBox.confirm('Hủy đơn và hoàn lại tồn kho?','Xác nhận');await shopAPI.cancelOrder(o.id);await loadOrders()}function canReview(o){if(o.channel==='POS')return o.status==='PAID'||o.status==='COMPLETED';return o.status==='DELIVERED'||o.status==='COMPLETED'}function openReview(o){reviewOrder.value={...o,items:o.items.filter((it,index,items)=>items.findIndex(x=>x.productId===it.productId)===index)};const f={};o.items.forEach(it=>{f[it.productId]={rating:5,comment:'',images:[]}});reviewForm.value=f;reviewOpen.value=true}async function submitReview(it){const f=reviewForm.value[it.productId];try{await shopAPI.submitReview({orderId:reviewOrder.value.id,productId:it.productId,rating:f.rating,comment:f.comment,images:f.images});ElMessage.success('Đã gửi đánh giá, cảm ơn bạn!')}catch(e){}}onMounted(async()=>{await Promise.all([loadCart(),loadOrders(),shopAPI.paymentMethods().then(r=>methods.value=r.data)])});watch(payOpen,v=>{if(!v)loadOrders()});</script>
<style scoped>.filters{display:flex;gap:10px;margin-bottom:18px}.filters>*{max-width:240px}.product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px}.product img{width:100%;height:150px;object-fit:cover;border-radius:12px}.product h3{margin:10px 0 4px}.product p{height:42px;overflow:hidden;color:var(--c-text2);font-size:.82rem}.price{font-weight:800;color:var(--c-accent);font-size:1.1rem;margin:10px 0}.price del{color:var(--c-text3);font-size:.8rem}.cart-row,.order-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--c-border2)}.total{text-align:right;font-size:1.2rem;font-weight:800;margin:16px}.order{margin-bottom:12px}.order>*{margin-bottom:8px}.pay{text-align:center}.pay img{width:280px;max-width:100%}.review-row{padding:12px 0;border-bottom:1px solid var(--c-border2)}.review-row>*{margin-bottom:6px;display:block}@media(max-width:700px){.filters{flex-wrap:wrap}.cart-row{flex-wrap:wrap}}</style>